    def __init__(
        self,
        model: str,
        input_tokens: int = 0,
        output_tokens: int = 0,
        cost_usd: float = 0.0,
    ):
        self._lock = threading.RLock()
        self.input_tokens = input_tokens
        self.output_tokens = output_tokens
        self._cost_usd = cost_usd
        self._cost_resolved = False
        self._model = self._resolve_model(model)

    @staticmethod
    def _resolve_model(model: str) -> str | None:
        """Resolve the tracked model URI, expanding gateway endpoints to their model.

        For ``gateway:/<endpoint>`` URIs, look up the endpoint's underlying model so
        that cost tracking can use provider pricing. Non-gateway URIs (and any string
        that is not a valid model URI) are stored as-is.
        """
        try:
            provider, endpoint_name = _parse_model_uri(model)
        except Exception:
            return model
        if provider == "gateway":
            return _resolve_model_for_gateway(endpoint_name)
        return model

